create extension if not exists pgcrypto;
create type public.app_role as enum ('admin','supervisor','customer');
create type public.product_status as enum ('draft','active','inactive','out_of_stock');
create type public.order_status as enum ('pending_confirmation','pending_payment','payment_review','confirmed','preparing','packed','shipped','delivered','cancelled','rejected','returned');
create type public.payment_status as enum ('pending','receipt_submitted','under_review','approved','rejected','paid');

create table public.profiles(id uuid primary key references auth.users on delete cascade,first_name text,last_name text,email text not null,phone text,status text not null default 'active' check(status in('active','inactive','blocked')),last_login_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.roles(id smallserial primary key,name app_role unique not null);
insert into public.roles(name) values('admin'),('supervisor'),('customer');
create table public.user_roles(user_id uuid references public.profiles on delete cascade,role_id smallint references public.roles,primary key(user_id,role_id));
create table public.addresses(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles on delete cascade,label text,address text not null,department text not null,municipality text not null,zone text,reference text,is_default boolean default false,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.categories(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,description text,image_url text,is_active boolean default true,display_order integer default 0,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.products(id uuid primary key default gen_random_uuid(),sku text unique not null,name text not null,slug text unique not null,short_description text,description text,price numeric(12,2) not null check(price>=0),sale_price numeric(12,2) check(sale_price>=0),cost numeric(12,2) check(cost>=0),category_id uuid references public.categories,brand text,stock integer not null default 0 check(stock>=0),reserved_stock integer not null default 0 check(reserved_stock>=0 and reserved_stock<=stock),minimum_stock integer not null default 5 check(minimum_stock>=0),status product_status default 'draft',featured boolean default false,allow_backorder boolean default false,main_image_url text,is_active boolean default true,deleted_at timestamptz,created_by uuid references public.profiles,updated_by uuid references public.profiles,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.product_images(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products on delete cascade,path text not null,alt_text text,display_order integer default 0,created_at timestamptz default now());
create table public.orders(id uuid primary key default gen_random_uuid(),order_number text unique not null,tracking_code text unique not null,customer_id uuid references public.profiles,is_guest boolean not null,buyer_first_name text not null,buyer_last_name text not null,phone text not null,email text,address text not null,department text not null,municipality text not null,zone text,reference text,subtotal numeric(12,2) not null,shipping_cost numeric(12,2) not null,discount numeric(12,2) default 0,total numeric(12,2) not null,payment_method text not null check(payment_method in('cash_on_delivery','bank_transfer')),payment_status payment_status not null default 'pending',status order_status not null,customer_notes text,internal_notes text,confirmed_at timestamptz,packed_at timestamptz,shipped_at timestamptz,delivered_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders,product_id uuid references public.products,sku text not null,product_name text not null,unit_price numeric(12,2) not null,quantity integer not null check(quantity>0),subtotal numeric(12,2) not null,image_url text,created_at timestamptz default now());
create table public.inventory_reservations(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products,order_id uuid not null references public.orders,quantity integer not null check(quantity>0),status text default 'active' check(status in('active','released','consumed','expired')),expires_at timestamptz not null,created_at timestamptz default now());
create table public.inventory_movements(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products,order_id uuid references public.orders,previous_quantity integer not null,quantity_change integer not null,resulting_quantity integer not null check(resulting_quantity>=0),movement_type text not null,reason text,responsible_user uuid references public.profiles,created_at timestamptz default now());
create table public.order_status_history(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders,old_status order_status,new_status order_status not null,public_comment text,internal_comment text,responsible_user uuid references public.profiles,created_at timestamptz default now());
create table public.bank_accounts(id uuid primary key default gen_random_uuid(),bank text not null,account_type text not null,account_number text not null,holder_name text not null,currency text default 'GTQ',instructions text,is_active boolean default true,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.bank_transfer_receipts(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders,path text not null,operation_number text,comments text,status payment_status default 'receipt_submitted',review_reason text,reviewed_by uuid references public.profiles,reviewed_at timestamptz,created_at timestamptz default now());
create table public.store_settings(id boolean primary key default true check(id),store_name text default 'Tráelo GT',logo_url text default '/traelo-gt-logo.png',phone text,whatsapp text default '50242902957',email text,address text,currency text default 'GTQ',shipping_cost numeric(12,2) default 25,reservation_hours integer default 24,allow_cash_on_delivery boolean default true,allow_bank_transfer boolean default true,maintenance_mode boolean default false,updated_at timestamptz default now());
insert into public.store_settings(id) values(true);
create table public.inventory_alerts(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products,type text not null,is_reviewed boolean default false,reviewed_by uuid references public.profiles,created_at timestamptz default now());
create table public.audit_logs(id bigint generated always as identity primary key,user_id uuid references public.profiles,action text not null,module text not null,record_id text,old_data jsonb,new_data jsonb,ip inet,user_agent text,created_at timestamptz default now());

create index products_active_idx on public.products(status,is_active) where deleted_at is null;create index products_category_idx on public.products(category_id);create index orders_phone_idx on public.orders(phone);create index orders_status_idx on public.orders(status,payment_status);create index orders_date_idx on public.orders(created_at desc);
create function public.touch_updated_at() returns trigger language plpgsql as $$begin new.updated_at=now();return new;end$$;
create trigger products_touch before update on public.products for each row execute function public.touch_updated_at();create trigger orders_touch before update on public.orders for each row execute function public.touch_updated_at();
create function public.on_auth_user_created() returns trigger language plpgsql security definer set search_path=public as $$declare customer_role smallint;begin insert into profiles(id,email,first_name,last_name) values(new.id,new.email,coalesce(new.raw_user_meta_data->>'first_name',''),coalesce(new.raw_user_meta_data->>'last_name',''));select id into customer_role from roles where name='customer';insert into user_roles values(new.id,customer_role);return new;end$$;
create trigger auth_user_created after insert on auth.users for each row execute function public.on_auth_user_created();
create function public.has_role(required_role app_role) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from user_roles ur join roles r on r.id=ur.role_id where ur.user_id=auth.uid() and r.name=required_role)$$;

alter table profiles enable row level security;alter table addresses enable row level security;alter table categories enable row level security;alter table products enable row level security;alter table orders enable row level security;alter table order_items enable row level security;alter table order_status_history enable row level security;alter table bank_transfer_receipts enable row level security;alter table audit_logs enable row level security;
create policy "public catalog categories" on categories for select using(is_active);create policy "public catalog products" on products for select using(status='active' and is_active and deleted_at is null);create policy "own profile" on profiles for select using(auth.uid()=id or has_role('admin'));create policy "update own profile" on profiles for update using(auth.uid()=id);create policy "own addresses" on addresses for all using(auth.uid()=user_id);create policy "own orders" on orders for select using(auth.uid()=customer_id or has_role('admin') or has_role('supervisor'));create policy "own order items" on order_items for select using(exists(select 1 from orders o where o.id=order_id and (o.customer_id=auth.uid() or has_role('admin') or has_role('supervisor'))));create policy "staff products" on products for all using(has_role('admin') or has_role('supervisor')) with check(has_role('admin') or has_role('supervisor'));

-- Guest checkout and tracking must call server-only Route Handlers using the service key.
-- Atomic order creation should lock product rows with SELECT ... FOR UPDATE,
-- recompute prices from products, increment reserved_stock and insert reservations
-- within one transaction. Never accept totals supplied by the browser.
